inline const Act* FindByVt(uint32_t rva) {
    for (int i = 0; i < kCount; ++i)
        if (kActs[i].vtRVA == rva) return &kActs[i];
    return nullptr;
}

inline bool IsCategory(uint32_t rva, const char* cat) {
    const Act* a = FindByVt(rva);
    if (!a) return false;
    for (int i = 0; cat[i] || a->category[i]; ++i)
        if (cat[i] != a->category[i]) return false;
    return true;
}

